// ============================================
// GERA OS 50 PRODUTOS
// ============================================
function generateProducts() {
  const products = [];
  const categories = Object.keys(PRODUCT_IMAGES);
  let id = 1;

  const distribution = {
    'decoração': 10,
    'árvore': 8,
    'luzes': 10,
    'presentes': 10,
    'roupas': 12
  };

  categories.forEach(cat => {
    const qty = distribution[cat];
    const names = productNames[cat];
    const images = PRODUCT_IMAGES[cat];

    for (let i = 0; i < qty; i++) {
      const basePrice = Math.floor(Math.random() * 200) + 20;

      products.push({
        id: id++,
        name: names[i % names.length] + (i >= names.length ? ` ${i}` : ''),
        category: cat,
        price: basePrice + 0.90,
        image: images[i],
        description: `Produto natalino de alta qualidade da categoria ${cat}. Perfeito para decorar sua casa e trazer o espírito do Natal!`,
        rating: (Math.random() * 2 + 3).toFixed(1)
      });
    }
  });

  return products;
}

const products = generateProducts();

// ============================================
// RECURSO 1: RENDERIZAÇÃO DO CATÁLOGO
// ============================================
let currentProducts = [...products];

function renderProducts(list) {
  const grid = document.getElementById('products-grid');
  const noResults = document.getElementById('no-results');

  if (list.length === 0) {
    grid.innerHTML = '';
    noResults.style.display = 'block';
    return;
  }

  noResults.style.display = 'none';

  grid.innerHTML = list.map(p => `
    <div class="product-card" data-id="${p.id}">
      <div class="product-img">
        <img
          src="${p.image}"
          alt="${p.name}"
          loading="lazy"
          onerror="this.style.display='none'"
        >
      </div>

      <h3 class="product-name">${p.name}</h3>

      <span class="product-category">${p.category}</span>

      <span class="product-price">
        R$ ${p.price.toFixed(2).replace('.', ',')}
      </span>

      <button class="add-btn" data-add="${p.id}">
        Adicionar ao Carrinho
      </button>
    </div>
  `).join('');
}

// ============================================
// RECURSO 2: BUSCA EM TEMPO REAL
// ============================================
const searchInput = document.getElementById('search-input');

let currentCategory = 'all';
let currentSort = 'default';

function applyFilters() {
  let filtered = [...products];

  if (currentCategory !== 'all') {
    filtered = filtered.filter(p => p.category === currentCategory);
  }

  const term = searchInput.value.toLowerCase().trim();

  if (term) {
    filtered = filtered.filter(p =>
      p.name.toLowerCase().includes(term) ||
      p.category.toLowerCase().includes(term)
    );
  }

  if (currentSort === 'price-asc') {
    filtered.sort((a, b) => a.price - b.price);
  } else if (currentSort === 'price-desc') {
    filtered.sort((a, b) => b.price - a.price);
  } else if (currentSort === 'name-asc') {
    filtered.sort((a, b) => a.name.localeCompare(b.name));
  }

  currentProducts = filtered;
  renderProducts(filtered);
}

searchInput.addEventListener('input', applyFilters);

// ============================================
// RECURSO 3: FILTRO POR CATEGORIA
// ============================================
document.querySelectorAll('.filter-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.filter-btn').forEach(b =>
      b.classList.remove('active')
    );

    btn.classList.add('active');
    currentCategory = btn.dataset.category;

    applyFilters();
  });
});

// ============================================
// RECURSO 4: ORDENAÇÃO
// ============================================
document.getElementById('sort-select').addEventListener('change', e => {
  currentSort = e.target.value;
  applyFilters();
});

// ============================================
// RECURSO 5: CARRINHO DE COMPRAS
// ============================================
let cart = JSON.parse(localStorage.getItem('natal-cart')) || [];

function saveCart() {
  localStorage.setItem('natal-cart', JSON.stringify(cart));
}

function updateCartCount() {
  const count = cart.reduce((sum, item) => sum + item.qty, 0);

  document.getElementById('cart-count').textContent = count;
}

function addToCart(productId) {
  const product = products.find(p => p.id === productId);

  if (!product) return;

  const existing = cart.find(item => item.id === productId);

  if (existing) {
    existing.qty++;
  } else {
    cart.push({ ...product, qty: 1 });
  }

  saveCart();
  updateCartCount();

  showToast(`✅ ${product.name} adicionado!`);
}

document.getElementById('products-grid').addEventListener('click', e => {
  const addBtn = e.target.closest('[data-add]');

  if (addBtn) {
    e.stopPropagation();
    addToCart(parseInt(addBtn.dataset.add));
    return;
  }

  const card = e.target.closest('.product-card');

  if (card) {
    openProductModal(parseInt(card.dataset.id));
  }
});

// ============================================
// RECURSO 6: MODAL DE DETALHES
// ============================================
function openProductModal(id) {
  const product = products.find(p => p.id === id);

  if (!product) return;

  document.getElementById('modal-body').innerHTML = `
    <div class="modal-product-img">
      <img src="${product.image}" alt="${product.name}">
    </div>

    <h2>${product.name}</h2>

    <span class="product-category">${product.category}</span>

    <p class="description">${product.description}</p>

    <p>⭐ Avaliação: ${product.rating} / 5</p>

    <p class="price">
      R$ ${product.price.toFixed(2).replace('.', ',')}
    </p>

    <button class="add-btn" data-add="${product.id}">
      Adicionar ao Carrinho 🛒
    </button>
  `;

  document.getElementById('modal-body')
    .querySelector('.add-btn')
    .addEventListener('click', () => {
      addToCart(product.id);
      closeModal('product-modal');
    });

  document.getElementById('product-modal').classList.add('active');
}

// ============================================
// RECURSO 7: MODAL DO CARRINHO
// ============================================
const cartModal = document.getElementById('cart-modal');

document.getElementById('cart-btn').addEventListener('click', () => {
  renderCart();
  cartModal.classList.add('active');
});

function renderCart() {
  const container = document.getElementById('cart-items');
  const totalEl = document.getElementById('cart-total');

  if (cart.length === 0) {
    container.innerHTML = '<p class="empty-cart">Seu carrinho está vazio 🎄</p>';
    totalEl.textContent = '0,00';
    return;
  }

  container.innerHTML = cart.map(item => `
    <div class="cart-item" data-id="${item.id}">
      <div class="cart-item-info">

        <div class="cart-item-name">
          <img
            src="${item.image}"
            alt="${item.name}"
            style="width:45px;height:45px;object-fit:contain;vertical-align:middle;"
          >
          ${item.name}
        </div>

        <div class="cart-item-price">
          R$ ${item.price.toFixed(2).replace('.', ',')}
        </div>
      </div>

      <div class="cart-qty">
        <button class="qty-btn" data-dec="${item.id}">−</button>
        <span>${item.qty}</span>
        <button class="qty-btn" data-inc="${item.id}">+</button>
      </div>

      <button class="remove-btn" data-remove="${item.id}">
        🗑️
      </button>
    </div>
  `).join('');

  const total = cart.reduce(
    (sum, item) => sum + item.price * item.qty,
    0
  );

  totalEl.textContent = total.toFixed(2).replace('.', ',');
}

// ============================================
// CONTROLES DO CARRINHO
// ============================================
document.getElementById('cart-items').addEventListener('click', e => {
  const inc = e.target.closest('[data-inc]');
  const dec = e.target.closest('[data-dec]');
  const rem = e.target.closest('[data-remove]');

  if (inc) {
    const item = cart.find(i => i.id === parseInt(inc.dataset.inc));

    if (item) item.qty++;

    saveCart();
    renderCart();
    updateCartCount();

  } else if (dec) {
    const item = cart.find(i => i.id === parseInt(dec.dataset.dec));

    if (item) {
      item.qty--;

      if (item.qty <= 0) {
        cart = cart.filter(i => i.id !== item.id);
      }
    }

    saveCart();
    renderCart();
    updateCartCount();

  } else if (rem) {
    cart = cart.filter(i => i.id !== parseInt(rem.dataset.remove));

    saveCart();
    renderCart();
    updateCartCount();
  }
});

// ============================================
// CHECKOUT
// ============================================
document.getElementById('checkout-btn').addEventListener('click', () => {
  if (cart.length === 0) {
    showToast('⚠️ Carrinho vazio!');
    return;
  }

  const total = cart.reduce(
    (sum, i) => sum + i.price * i.qty,
    0
  );

  showToast(
    `🎉 Pedido de R$ ${total.toFixed(2).replace('.', ',')} finalizado! Feliz Natal!`
  );

  cart = [];

  saveCart();
  updateCartCount();
  renderCart();

  setTimeout(() => closeModal('cart-modal'), 1500);
});

// ============================================
// RECURSO 8: TOAST E MODAIS
// ============================================
function showToast(message) {
  const toast = document.getElementById('toast');

  toast.textContent = message;
  toast.classList.add('show');

  clearTimeout(toast._timer);

  toast._timer = setTimeout(
    () => toast.classList.remove('show'),
    2500
  );
}

function closeModal(id) {
  document.getElementById(id).classList.remove('active');
}

document.querySelectorAll('.close-modal').forEach(btn => {
  btn.addEventListener('click', () => {
    closeModal(btn.dataset.modal);
  });
});

// Fecha modal ao clicar fora
document.querySelectorAll('.modal').forEach(modal => {
  modal.addEventListener('click', e => {
    if (e.target === modal) {
      modal.classList.remove('active');
    }
  });
});

// Fecha com ESC
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    document.querySelectorAll('.modal.active').forEach(m => {
      m.classList.remove('active');
    });
  }
});

// ============================================
// INICIALIZAÇÃO
// ============================================
renderProducts(products);
updateCartCount();

console.log(`🎄 Loja iniciada com ${products.length} produtos!`);